mapper.select:
SELECT NVL(c.APPROVAL_MEMO, '반려 사유가 등록되지 않았습니다.')
FROM CLASS c
WHERE c.OPERATOR_CODE = #{authorCode}
  AND c.CLASS_CODE = #{classCode}
  AND c.APPROVAL_STATUS = '반려'
  AND c.STATUS = '대기중'

mapper.update:
UPDATE CLASS
SET STATUS = '모집중'
WHERE CLASS_CODE = #{classCode}
  AND OPERATOR_CODE = #{authorCode}
  AND APPROVAL_STATUS = '승인'
  AND STATUS = '대기중'

mapper.select:
SELECT NVL(c.APPROVAL_MEMO, '관리자에 의해 클래스 운영이 중지되었습니다.')
FROM CLASS c
WHERE c.OPERATOR_CODE = #{authorCode}
  AND c.CLASS_CODE = #{classCode}
  AND c.APPROVAL_STATUS = '중지'
  AND c.STATUS = '대기중'
